WITH EnhBadges AS (
    SELECT
        b.UserId,
        CONCAT_WS(' | ', LISTAGG(CASE WHEN b.Class = 1 THEN 'Gold: ' || b.Name
                     WHEN b.Class = 2 THEN 'Silver: ' || b.Name
                     ELSE
                         'Bronze: ' || b.Name END, '; ') 
            WITHIN GROUP (ORDER BY b.Date)) AS BadgesList,
        COUNT(*) OVER (PARTITION BY b.UserId) AS UserBadgeCount,
        COUNT(DISTINCT b.Class) OVER (PARTITION BY b.UserId) AS NexusModifier
    FROM Badges b
), LatestEdits AS (
    SELECT okqu.AnswerId,
    MAX(ph.CreationDate) AS LatestEditDate
    FROM PostTypes ptq
    INNER JOIN Posts pq ON ptq.Id = pq.PostTypeId AND ptq.Name = 'Question'
